import{_ as l,o,c as s,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Ceph on Windows - Alessandro Pilotti, Cloudbase Solutions","description":"","frontmatter":{"title":"Ceph on Windows - Alessandro Pilotti, Cloudbase Solutions","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","Windows集成","分布式存储","开源技术","云存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_on_Windows_-_Alessandro_Pilotti_Cloudbase_Solutions.md","filePath":"posts/2023/Ceph_on_Windows_-_Alessandro_Pilotti_Cloudbase_Solutions.md","lastUpdated":1780459816000}'),n={name:"posts/2023/Ceph_on_Windows_-_Alessandro_Pilotti_Cloudbase_Solutions.md"};function e(p,i,r,d,a,u){return o(),s("div",null,[...i[0]||(i[0]=[t("<p>会议纪要</p><p><strong>会议主题：</strong> Ceph与Windows集成解决方案介绍</p><p><strong>主讲人：</strong> Alessandra Pilotti, Cloudbase Solutions CEO</p><p><strong>会议内容总结：</strong></p><ol><li><p><strong>背景介绍：</strong></p><ul><li>Ceph作为开源分布式存储解决方案，在Linux环境中表现出色。</li><li>Windows Server在企业市场中占据重要地位。</li><li>传统Ceph iSCSI Gateway在性能上存在局限。</li></ul></li><li><p><strong>合作伙伴关系：</strong></p><ul><li>Cloud-based Solutions与Ceph合作，致力于改善Windows环境下的Ceph性能。</li><li>合作成果开源，并已集成到Ceph社区中。</li></ul></li><li><p><strong>技术目标：</strong></p><ul><li>提供与Linux环境下相似的用户体验和命令行接口。</li><li>确保Ceph在Windows上运行时，Windows管理员也能感到熟悉。</li><li>实现高性能，目标是超越传统的iSCSI Gateway，并接近Linux原生性能。</li></ul></li><li><p><strong>架构与实现：</strong></p><ul><li>OSD运行在Linux上，Windows上运行一个用户空间进程（RBD Windows）。</li><li>开发了一个新的内核驱动（wimbd.sys）来处理磁盘操作。</li><li>支持的Windows版本包括Windows Server 2016, 2019, 2022，以及Windows 10和11。</li></ul></li><li><p><strong>性能优化：</strong></p><ul><li>通过实现Device I/O Control和改进I/O并发性来提升性能。</li><li>测试结果显示，性能显著优于iSCSI Gateway。</li></ul></li><li><p><strong>安全性与认证：</strong></p><ul><li>驱动程序已通过Cloud-based Solutions的认证，未来计划通过Microsoft认证。</li><li>Microsoft认证版本将支持安全启动功能。</li></ul></li><li><p><strong>未来工作：</strong></p><ul><li>增加对Windows集群的支持，包括集群共享卷和扩展文件服务器。</li><li>持续的维护和改进工作，包括错误修复和社区集成。</li></ul></li><li><p><strong>演示内容：</strong></p><ul><li>展示了如何在Windows Server上安装和配置Ceph。</li><li>演示了Ceph卷的创建、映射和管理。</li><li>展示了Ceph文件系统（CephFS）在Windows上的使用。</li><li>演示了Hyper-V与Ceph的集成，以及如何在集群环境中使用Ceph。</li></ul></li></ol><p><strong>后续行动计划：</strong></p><ul><li>继续与Ceph社区合作，推动技术发展和集成。</li><li>提供持续的技术支持和咨询服务。</li><li>完成Microsoft认证流程，发布认证驱动程序。</li></ul><p><strong>会议结束语：</strong></p><ul><li>Alessandra Pilotti感谢大家的参与，并表示愿意进一步讨论项目细节和提供支持。</li></ul><p><strong>备注：</strong></p><ul><li>会议中提到的所有技术细节和演示步骤均为Ceph与Windows集成解决方案的关键组成部分。</li></ul>",11)])])}const g=l(n,[["render",e]]);export{C as __pageData,g as default};
